head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vSecuGrpId = "";
scwin.vLIST_STAT_CD = "Y";
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
        rdo_1_1.setValue("1");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tabList_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabList_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === 1) {
            rdo_1_1.setValue("1");
            rdo_1_2.setValue("2");
            txb_ISU_CD.setValue("");
            txb_ISU_NM.setValue("");
            txb_ISUR_CD1.setValue("");
            txb_COM_NM1.setValue("");
            await scwin.search();
        } else if (nIndex === 2) {
            await scwin.search2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.tabList_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 건수 : " + rowcount);
        // dts.RowPosition = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts2_OnLoadError
 * @description dts2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.dts2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts2_OnLoadCompleted
 * @description dts2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts2_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt2.setValue("총 건수 : " + rowcount);
        // dts2.RowPosition = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.dts2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (tabList.getSelectedTabIndex() === 1) {
            // 종목 선택
            if (rdo_1_1.getValue() === "1") {
                if (txb_ISU_CD.getValue() === "") {
                    await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                    return true;
                }
            }
            scwin.fn_GetPar = scwin.getParNew;
            scwin.fn_SetPar = undefined;
            if (rdo_1_2.getValue() === "1") {
                await scwin.newCreateFrame();
            } else {
                await scwin.newpreCreateFrame();
            }
        } else {
            scwin.fn_GetPar = scwin.getParNew2;
            scwin.fn_SetPar = undefined;
            await scwin.newCreateFrame2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        // 엑셀저장
        if (tabList.getSelectedTabIndex() === 1) {
            $c.stf.doLogSave("ULDSTF70034.xml", SCREN_PROCS_TP_CD_07);
            if (dts.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd, {fileName: "상장폐지내역", type: "8"});
            } else {
                await $c.win.alert(NO_EXCEL_DATA);
            }
        } else {
            $c.stf.doLogSave("ULDSTF70034.xml", SCREN_PROCS_TP_CD_07);
            if (dts2.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd2, {fileName: "만기에 의한 상장폐지내역", type: "8"});
            } else {
                await $c.win.alert(NO_EXCEL_DATA);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_OnDblClick
 * @description grd 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_OnDblClick = async function(row, colid) {
    try {
        scwin.vIsurCd = dts.getCellData(dts.getRowPosition(), "ISUR_CD");
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.grd_OnDblClick" });
    }
};

/**
 * @method
 * @name grd2_OnDblClick
 * @description grd2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd2_OnDblClick = async function(row, colid) {
    try {
        scwin.vIsurCd = dts2.getCellData(dts2.getRowPosition(), "ISUR_CD");
        scwin.fn_GetPar = scwin.getParUpdate2; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.grd2_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (rdo_1_1.getValue() === "1") {
            if (txb_ISU_CD.getValue() === "") {
                await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                return true;
            }
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Search2_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search2_onclick = async function() {
    try {
        await scwin.search2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.img_Search2_onclick" });
    }
};

/**
 * @method
 * @name btn_iSU_CD_onclick
 * @description btn_iSU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_iSU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsu;
        scwin.fn_SetPar = scwin.setParIsu;
        $c.lcd.fn_PopFindDigitalIsuAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.btn_iSU_CD_onclick" });
    }
};

/**
 * @method
 * @name rdo_1_1_onclick
 * @description rdo_1_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_1_1_onclick = function() {
    try {
        // rdo_1_2.CodeValue ="2";
        scwin.changeRadioBtn(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.rdo_1_1_onclick" });
    }
};

/**
 * @method
 * @name rdo_1_2_onclick
 * @description rdo_1_2 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_1_2_onclick = async function() {
    try {
        // rdo_1_1.CodeValue ="2";
        scwin.changeRadioBtn(2);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70034.rdo_1_2_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM1_onclick
 * @description img_COM_NM1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM1_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lcd.fn_PopFindDigitalIsurAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.img_COM_NM1_onclick" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onchange
 * @description txb_ISU_CD 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onchange = function() {
    try {
        txb_ISU_NM.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.txb_ISU_CD_onchange" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD1_onchange
 * @description txb_ISUR_CD1 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD1_onchange = function() {
    try {
        txb_COM_NM1.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70034.txb_ISUR_CD1_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 상장폐지 조회(Tab 1)

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (rdo_1_1.getValue() === "1") {
        // 종목조회
        url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_1_2.getValue() === "1") {
        // 상장신청인 조회
        if (txb_ISUR_CD1.getValue() === "") {
            url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT;
        } else {
            url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + txb_ISUR_CD1.getValue();
        }
    }
    url += "&SCREN_ID=" + "ULDSTF70034.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

// 만기에 의한 상장폐지(Tab2)

/**
 * @method
 * @name search2
 * @description search2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search2 = async function() {
    url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999";
    url += "&SCREN_ID=" + "ULDSTF70034.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts2",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 상장신청인 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = txb_ISUR_CD1.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_COM_NM1.getValue(); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        scwin.changeRadioBtn(2);
        if (tabList.getSelectedTabIndex() === "1") {
            txb_ISUR_CD1.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM1.setValue(arrPar[0].ISUR_NM);
            await scwin.search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD === "D") {
        if (tabList.getSelectedTabIndex() === "1") {
            img_Regist.setDisabled(true);
            img_Regist.setBackgroundImage("../img/btn_new_d.gif");
        } else {
            img_Regist2.setDisabled(true);
            img_Regist2.src = "../img/btn_new_d.gif";
        }
    } else {
        if (tabList.getSelectedTabIndex() === "1") {
            img_Regist.setDisabled(false);
            img_Regist.setBackgroundImage("../img/btn_new.gif");
        } else {
            img_Regist2.setDisabled(false);
            img_Regist2.src = "../img/btn_new.gif";
        }
    }
};

/**
 * @method
 * @name getParIsu
 * @description dialog 호출용 함수 종목명 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    if (tabList.getSelectedTabIndex() === "1") {
        arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤

    }
    arrPar[2] = "";
    return arrPar.length;
};

/**
 * @method
 * @name setParIsu
 * @description set Par Isu 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsu = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        scwin.changeRadioBtn(1);
        if (tabList.getSelectedTabIndex() === "1") {
            txb_ISU_CD.setValue(arrPar[0].ISU_CD);
            txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
            await scwin.search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.vSecuGrpId = arrPar[0].SECUGRP_ID;
    }
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD === "D") {
        if (tabList.getSelectedTabIndex() === "1") {
            img_Regist.setDisabled(true);
            img_Regist.setBackgroundImage("../img/btn_new_d.gif");
        } else {
            img_Regist2.setDisabled(true);
            img_Regist2.src = "../img/btn_new_d.gif";
        }
    } else {
        if (tabList.getSelectedTabIndex() === "1") {
            img_Regist.setDisabled(false);
            img_Regist.setBackgroundImage("../img/btn_new.gif");
        } else {
            img_Regist2.setDisabled(false);
            img_Regist2.src = "../img/btn_new.gif";
        }
    }
};

/**
 * @method
 * @name getParUpdate
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    if (rdo_1_1.getValue() === "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() === "1") {
        if (txb_ISUR_CD1.getValue() === "") {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.vSecuGrpId;
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[7] = dts.getCellData(dts.getRowPosition(), "DSC_YN"); // 공시여부

    return arrPar.length;
};

/**
 * @method
 * @name getParNew
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    if (rdo_1_1.getValue() === "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명

        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() === "1") {
        if (txb_ISUR_CD1.getValue() === "") {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = txb_ISUR_CD1.getValue(); // 발행기관코드값
            arrPar[1] = txb_COM_NM1.getValue(); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.vSecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[7] = ""; // 공시여부

};

