/**
 * @method
 * @name newCreateFrame
 * @description new Create Frame 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newCreateFrame = async function() {
    const options = {
        id: "ULDSTF70034_N1",
        title: " 상장폐지",
        type: "browserPopup",
        width: "740px",
        height: "450px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../digital/ULDSTF70034_N1.gfm", options);
    await scwin.search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};

